"""依頼と本文・参照資料の適用条件から選んだ合成の提出例。"""


SELECTIONS = {
    'article-eval': (['research-standards', 'design-review'], ['source-dating']),
    'paraphrase': (['research-standards', 'design-review'], ['source-dating']),
    'edit-and-check': (['writing-quality', 'run-checks'], ['config-consumers']),
    'bug-explain': (['bug-analysis'], ['incident-history']),
    'known-fact': ([], []),
    'boundary': (['research-standards', 'writing-quality'], ['glossary']),
}


def select(request_id: str) -> dict[str, list[str]]:
    """依頼IDに対し、初期選択と本文を読んだ後の追加選択の識別子を返す。"""
    initial, additional = SELECTIONS[request_id]
    return {"initial": list(initial), "additional": list(additional)}

